EDITORIAL = {item["name"]: item for item in json.loads((Path(__file__).parent / "editorial-sources.json").read_text())}
FOCAL = {"biodiversita-cetaceo":"50% 100%", "biodiversita-mammifero-bosco":"50% 10%", "economia-circolare-mano":"50% 55%", "applicazione-protezione-sport":"50% 20%"}
from turtle_art import turtle_art

def photo(name,alt,caption='',cls=''):
    # Keep original documents, but serve new stock photographs at responsive sizes.
    if name in EDITORIAL:
        item = EDITORIAL[name]
        base = f'assets/editorial/{name}'
        is_gallery = name.startswith('applicazione-') or (name.startswith('biodiversita-') and name != 'biodiversita-mondo-puzzle')
        sizes = '(max-width:760px) 44vw, (max-width:1100px) 28vw, 360px' if is_gallery else '(max-width:760px) 90vw, 700px'
        position = FOCAL.get(name, '50% 50%')
        image = f'<img src="{base}-hd.webp" srcset="{base}-sm.webp {item["smallWidth"]}w, {base}-hd.webp {item["width"]}w" sizes="{sizes}" alt="{alt}" loading="lazy" decoding="async" width="{item["width"]}" height="{item["height"]}" style="object-position:{position}">'
    else:
        image = f'<img src="assets/brochure/{name}.webp" alt="{alt}" loading="lazy" width="900" height="700">'
    return f'<figure class="editorial-photo {cls}">'+image+'</figure>'

def heading(kicker,title,id):
    return f'<div class="editorial-head"><h2 class="display small" id="{id}" data-lines>{title}</h2></div>'

def gallery(items,cls=''):
    return '<div class="brochure-gallery '+cls+'" data-stagger>'+''.join(photo(name,label,label) for name,label in items)+'</div>'

